const ai_kb_graph_entity = data[0].id;
const type = data[0].type;

// 确保 type 有效
if (type == null) {
    return;
}

const graph_tree = view.getCtrl("TREE", "treeexpbar2_tree");
const graph = graph_tree.graph;

// 使用 Set 存储保留节点ID（支持 has() 检查）
const keepNodeIds = new Set([ai_kb_graph_entity]);
const hideElementIds = [];

// 1. 收集所有非同类型节点（隐藏节点）
graph.getNodeData().forEach(node => {
    // 跳过无类型节点（避免比较 undefined）
    if (node.data.type == null || node.data.type !== type) {
        hideElementIds.push(node.id);
    } else {
        keepNodeIds.add(node.id); // 自动去重
    }
});

// 2. 收集需要隐藏的边（任一端点不在保留集合中）
graph.getEdgeData().forEach(edge => {
    const sourceId = edge.source;
    const targetId = edge.target;
    if (!keepNodeIds.has(sourceId) || !keepNodeIds.has(targetId)) {
        hideElementIds.push(edge.id);
    }
});

// 3. 隐藏节点和边
await graph.hideElement(hideElementIds);
await graph.focusElement(ai_kb_graph_entity);
graph.zoomTo(1.1);

